import{_ as t,o as a,c as r,a4 as o}from"./chunks/framework.CAgiNEKA.js";const p=JSON.parse('{"title":"Cherry Studio 接入指南","description":"","frontmatter":{"title":"Cherry Studio 接入指南","date":"2026-05-18T00:00:00.000Z","category":"拓展","tags":["Cherry Studio","AI客户端","接入教程","开源"]},"headers":[],"relativePath":"connect/cherry-studio.md","filePath":"connect/cherry-studio.md","lastUpdated":1779073000000}'),d={name:"connect/cherry-studio.md"};function h(i,e,n,c,s,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="cherry-studio-接入指南" tabindex="-1">Cherry Studio 接入指南 <a class="header-anchor" href="#cherry-studio-接入指南" aria-label="Permalink to &quot;Cherry Studio 接入指南&quot;">​</a></h1><p>开源免费的全能 AI 桌面客户端，接入熊猫Token，一个 Key 用尽所有模型。</p><p><strong>预计用时：5 分钟 · 支持平台：Win / Mac / Linux · GitHub Stars：42k+</strong></p><hr><h2 id="什么是-cherry-studio" tabindex="-1">什么是 Cherry Studio？ <a class="header-anchor" href="#什么是-cherry-studio" aria-label="Permalink to &quot;什么是 Cherry Studio？&quot;">​</a></h2><p>Cherry Studio 是一款开源免费的桌面 AI 客户端，支持 Windows、macOS、Linux 三平台。内置 300+ 预设 AI 助手，支持多模型同时对话、知识库、AI 绘图、翻译等功能。配合熊猫Token平台，只需一个 API Key 即可调用所有大模型。</p><hr><h2 id="step-01-下载安装-cherry-studio" tabindex="-1">Step 01：下载安装 Cherry Studio <a class="header-anchor" href="#step-01-下载安装-cherry-studio" aria-label="Permalink to &quot;Step 01：下载安装 Cherry Studio&quot;">​</a></h2><h3 id="_1-前往官方-github-下载" tabindex="-1">1. 前往官方 GitHub 下载 <a class="header-anchor" href="#_1-前往官方-github-下载" aria-label="Permalink to &quot;1. 前往官方 GitHub 下载&quot;">​</a></h3><p>访问 <a href="https://github.com/CherryHQ/cherry-studio/releases" target="_blank" rel="noreferrer">github.com/CherryHQ/cherry-studio/releases</a>，找到最新版本。</p><h3 id="_2-选择对应系统版本" tabindex="-1">2. 选择对应系统版本 <a class="header-anchor" href="#_2-选择对应系统版本" aria-label="Permalink to &quot;2. 选择对应系统版本&quot;">​</a></h3><ul><li>Windows：下载 <code>.exe</code> 安装包</li><li>macOS：下载 <code>.dmg</code></li><li>Linux：下载 <code>.AppImage</code> 或 <code>.deb</code></li></ul><h3 id="_3-安装并启动" tabindex="-1">3. 安装并启动 <a class="header-anchor" href="#_3-安装并启动" aria-label="Permalink to &quot;3. 安装并启动&quot;">​</a></h3><p>Windows 双击 .exe 一路下一步即可，macOS 拖入应用程序文件夹。安装完成后启动 Cherry Studio。</p><hr><h2 id="step-02-获取熊猫token-api-key" tabindex="-1">Step 02：获取熊猫Token API Key <a class="header-anchor" href="#step-02-获取熊猫token-api-key" aria-label="Permalink to &quot;Step 02：获取熊猫Token API Key&quot;">​</a></h2><h3 id="_1-登录熊猫token平台" tabindex="-1">1. 登录熊猫Token平台 <a class="header-anchor" href="#_1-登录熊猫token平台" aria-label="Permalink to &quot;1. 登录熊猫Token平台&quot;">​</a></h3><p>访问 <a href="https://www.pandatoken.net" target="_blank" rel="noreferrer">www.pandatoken.net</a>，注册并登录账号。</p><h3 id="_2-进入控制台获取密钥" tabindex="-1">2. 进入控制台获取密钥 <a class="header-anchor" href="#_2-进入控制台获取密钥" aria-label="Permalink to &quot;2. 进入控制台获取密钥&quot;">​</a></h3><p>点击顶部导航「控制台」→「令牌 / API Keys」，创建新的令牌并复制。</p><hr><h2 id="step-03-在-cherry-studio-中配置" tabindex="-1">Step 03：在 Cherry Studio 中配置 <a class="header-anchor" href="#step-03-在-cherry-studio-中配置" aria-label="Permalink to &quot;Step 03：在 Cherry Studio 中配置&quot;">​</a></h2><h3 id="_1-打开设置" tabindex="-1">1. 打开设置 <a class="header-anchor" href="#_1-打开设置" aria-label="Permalink to &quot;1. 打开设置&quot;">​</a></h3><p>点击左下角「设置」图标，进入「模型服务」页面。</p><h3 id="_2-添加自定义服务商" tabindex="-1">2. 添加自定义服务商 <a class="header-anchor" href="#_2-添加自定义服务商" aria-label="Permalink to &quot;2. 添加自定义服务商&quot;">​</a></h3><p>向下滚动找到「添加自定义服务商」，点击后填写以下信息：</p><table tabindex="0"><thead><tr><th>配置项</th><th>填写内容</th></tr></thead><tbody><tr><td>名称</td><td>熊猫Token（自定义）</td></tr><tr><td>API 地址 (Base URL)</td><td><code>https://www.pandatoken.net/v1</code></td></tr><tr><td>API Key</td><td>你从平台复制的令牌</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">注意</p><p>Base URL 只填到 <code>/v1</code> 结尾，Cherry Studio 会自动拼接后面的路径。</p></div><h3 id="_3-开启开关并添加模型" tabindex="-1">3. 开启开关并添加模型 <a class="header-anchor" href="#_3-开启开关并添加模型" aria-label="Permalink to &quot;3. 开启开关并添加模型&quot;">​</a></h3><p>确保服务商右上角的开关是<strong>打开</strong>状态。点击「管理」按钮，手动添加你想使用的模型名称，例如 <code>deepseek-v3</code>、<code>gpt-4o</code>、<code>claude-3-5-sonnet-20241022</code> 等。</p><h3 id="_4-开始对话" tabindex="-1">4. 开始对话 <a class="header-anchor" href="#_4-开始对话" aria-label="Permalink to &quot;4. 开始对话&quot;">​</a></h3><p>点击左上角聊天图标，在对话框顶部的模型选择器中选择刚刚添加的模型，即可开始使用！</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>提示&quot;连接失败&quot;或&quot;API Key 无效&quot;</strong></p><p>请确认 Base URL 末尾不要加 <code>/chat/completions</code>，只需 <code>https://www.pandatoken.net/v1</code> 即可，同时确认开关已打开。</p><p><strong>模型列表为空</strong></p><p>自定义服务商不会自动拉取模型列表，需要手动点击「+ 添加」按钮，输入准确的模型 ID。</p><hr><p>配置完成！Cherry Studio 已成功接入熊猫Token平台，一个 Key 畅用所有模型。</p>',40)])])}const b=t(d,[["render",h]]);export{p as __pageData,b as default};
